#!/usr/bin/env python3
"""
cleanup_logs.py

Finds and removes all .bash_history files in /home and /root directories.
Uses os.walk to traverse directories and os.remove to delete matching files.
"""

import os


TARGET_FILENAME = ".bash_history"
SEARCH_ROOTS = ["/home", "/root"]


def remove_bash_history_files(roots):
    """Walk each root directory and remove any .bash_history files found."""
    removed = []
    errors = []

    for root in roots:
        if not os.path.isdir(root):
            print(f"Skipping {root}: not a directory or does not exist.")
            continue

        for dirpath, _dirnames, filenames in os.walk(root):
            for filename in filenames:
                if filename == TARGET_FILENAME:
                    full_path = os.path.join(dirpath, filename)
                    try:
                        os.remove(full_path)
                        removed.append(full_path)
                        print(f"Removed: {full_path}")
                    except OSError as exc:
                        errors.append((full_path, str(exc)))
                        print(f"Failed to remove {full_path}: {exc}")

    return removed, errors


def main():
    removed, errors = remove_bash_history_files(SEARCH_ROOTS)
    print()
    print(f"Total files removed: {len(removed)}")
    if errors:
        print(f"Total errors: {len(errors)}")


if __name__ == "__main__":
    main()
